import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Integrations — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"integrations-03-advanced-and-customization.md","filePath":"integrations-03-advanced-and-customization.md"}'),s={name:"integrations-03-advanced-and-customization.md"};function i(r,t,c,h,d,l){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="integrations-—-advanced-features-customization" tabindex="-1">Integrations — Advanced Features &amp; Customization <a class="header-anchor" href="#integrations-—-advanced-features-customization" aria-label="Permalink to &quot;Integrations — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Sync strategy, status mapping, managing multiple projects, and getting the most from each integration</em></p><hr><h2 id="choosing-the-right-jira-sync-configuration" tabindex="-1">Choosing the Right JIRA Sync Configuration <a class="header-anchor" href="#choosing-the-right-jira-sync-configuration" aria-label="Permalink to &quot;Choosing the Right JIRA Sync Configuration&quot;">​</a></h2><p>The three JIRA sync options — Manual, Automatic, and Webhooks — are not mutually exclusive. Most teams should run both Automatic Sync and Webhooks simultaneously for maximum reliability.</p><table tabindex="0"><thead><tr><th>Configuration</th><th>Best for</th></tr></thead><tbody><tr><td>Manual only</td><td>Teams that want explicit control and rarely need real-time accuracy</td></tr><tr><td>Automatic Sync only</td><td>Teams that can tolerate a short lag (e.g. hourly) before updates appear</td></tr><tr><td>Webhooks only</td><td>Teams that need instant sync but want a simple setup</td></tr><tr><td>Automatic + Webhooks</td><td>Most teams — webhooks provide real-time sync, automatic polling acts as a safety net if a webhook event is missed</td></tr></tbody></table><h3 id="why-run-both-automatic-and-webhooks" tabindex="-1">Why run both Automatic and Webhooks? <a class="header-anchor" href="#why-run-both-automatic-and-webhooks" aria-label="Permalink to &quot;Why run both Automatic and Webhooks?&quot;">​</a></h3><p>Webhooks can occasionally miss events — network issues, JIRA downtime, or configuration gaps can cause a change to not propagate. Automatic Sync catches anything the webhook missed on the next polling cycle. Running both gives you real-time accuracy with built-in redundancy.</p><hr><h2 id="status-mapping-best-practices" tabindex="-1">Status Mapping Best Practices <a class="header-anchor" href="#status-mapping-best-practices" aria-label="Permalink to &quot;Status Mapping Best Practices&quot;">​</a></h2><p>Status mapping is the most important configuration step in the JIRA integration, and the most commonly misconfigured one. A few things that matter:</p><h3 id="map-all-jira-statuses" tabindex="-1">Map all JIRA statuses <a class="header-anchor" href="#map-all-jira-statuses" aria-label="Permalink to &quot;Map all JIRA statuses&quot;">​</a></h3><p>JIRA workflows often have more statuses than you&#39;d expect — In Review, UAT, Blocked, Waiting, Ready for Dev, and so on. Any JIRA status that isn&#39;t mapped will not update Feature status in Lodestone. Check your JIRA workflow for every possible status and map each one.</p><h3 id="update-mappings-when-jira-workflows-change" tabindex="-1">Update mappings when JIRA workflows change <a class="header-anchor" href="#update-mappings-when-jira-workflows-change" aria-label="Permalink to &quot;Update mappings when JIRA workflows change&quot;">​</a></h3><p>If your engineering team changes their JIRA workflow — adding new statuses, renaming existing ones, or changing their board configuration — your status mapping may become stale. An unmapped status means Lodestone stops receiving updates for Features in that state.</p><h3 id="use-the-most-semantically-accurate-match" tabindex="-1">Use the most semantically accurate match <a class="header-anchor" href="#use-the-most-semantically-accurate-match" aria-label="Permalink to &quot;Use the most semantically accurate match&quot;">​</a></h3><p>When a JIRA status doesn&#39;t map cleanly to a Lodestone stage, choose the closest match. For example, a &quot;Ready for QA&quot; status in JIRA is closer to &quot;In Progress&quot; than &quot;Completed&quot; — keep it in progress until it&#39;s actually done.</p><hr><h2 id="managing-multiple-jira-projects" tabindex="-1">Managing Multiple JIRA Projects <a class="header-anchor" href="#managing-multiple-jira-projects" aria-label="Permalink to &quot;Managing Multiple JIRA Projects&quot;">​</a></h2><p>A workspace can connect to multiple JIRA projects, each with its own sync configuration and status mapping. This is useful for organizations with separate JIRA projects per team, product line, or region.</p><p>A few things to consider:</p><ul><li>Each project has its own status mapping — if your JIRA projects use different workflows, configure each mapping independently</li><li>Features created in Lodestone are assigned to a specific JIRA project at the point of sync — make sure the correct project is selected when linking or auto-syncing a Feature</li><li>If projects share the same JIRA statuses, you can apply a consistent mapping across them; if they diverge, map each separately</li></ul><hr><h2 id="choosing-the-right-jira-object-level" tabindex="-1">Choosing the Right JIRA Object Level <a class="header-anchor" href="#choosing-the-right-jira-object-level" aria-label="Permalink to &quot;Choosing the Right JIRA Object Level&quot;">​</a></h2><p>When connecting JIRA, you choose which object level Lodestone Features map to: Epic, Story, Task, or Subtask. This is an important architectural decision.</p><table tabindex="0"><thead><tr><th>JIRA level</th><th>When to use</th></tr></thead><tbody><tr><td>Epic</td><td>Features represent large initiatives; each Feature maps to a JIRA Epic containing multiple stories</td></tr><tr><td>Story</td><td>Features represent user-facing capabilities; maps directly to JIRA Stories</td></tr><tr><td>Task</td><td>Features represent work items of any type; Task is the most flexible mapping</td></tr><tr><td>Subtask</td><td>Features represent granular work; less common, used in highly structured workflows</td></tr></tbody></table><p>Most teams use Epic or Story. Choosing the right level depends on how granularly your team tracks work in JIRA relative to how you define Features in Lodestone.</p><hr><h2 id="asana-sync-behavior" tabindex="-1">Asana Sync Behavior <a class="header-anchor" href="#asana-sync-behavior" aria-label="Permalink to &quot;Asana Sync Behavior&quot;">​</a></h2><p>The Asana integration operates at the individual item level — each Backlog item you push to Asana becomes its own Asana task. Unlike JIRA, there is no workspace-wide continuous sync: you initiate the connection per item by clicking Push to Asana on the item detail page.</p><p>Once a Backlog item is linked to an Asana task:</p><ul><li><strong>Status updates from Asana sync back to Lodestone automatically</strong> — when the Asana task status changes (e.g. moves to Complete), the Lodestone Backlog item&#39;s status updates accordingly</li><li><strong>The link is permanent for that item</strong> — the Asana task ID is stored on the Backlog item; disconnecting and reconnecting the integration does not break existing item links</li><li>The mapping between Asana task statuses and Lodestone status stages follows the status mapping configuration in Settings &gt; Integrations</li></ul><h3 id="asana-vs-jira-choosing-between-them" tabindex="-1">Asana vs. JIRA: choosing between them <a class="header-anchor" href="#asana-vs-jira-choosing-between-them" aria-label="Permalink to &quot;Asana vs. JIRA: choosing between them&quot;">​</a></h3><p>Both integrations keep Backlog item status in sync with a delivery tool, but they work differently:</p><table tabindex="0"><thead><tr><th></th><th>Asana</th><th>JIRA</th></tr></thead><tbody><tr><td>Sync scope</td><td>Per-item push</td><td>Workspace-wide automatic sync</td></tr><tr><td>Setup complexity</td><td>Low — Personal Access Token + project selection</td><td>Higher — API key, object level, status mapping, optional webhooks</td></tr><tr><td>Real-time sync</td><td>Status updates from Asana are polled automatically</td><td>Webhooks + polling available</td></tr><tr><td>Best for</td><td>Teams using Asana for task management</td><td>Teams using JIRA for engineering workflows</td></tr></tbody></table><p>You can run both integrations simultaneously if your team uses both tools.</p><hr><h2 id="discovery-integrations-choosing-the-right-one" tabindex="-1">Discovery Integrations: Choosing the Right One <a class="header-anchor" href="#discovery-integrations-choosing-the-right-one" aria-label="Permalink to &quot;Discovery Integrations: Choosing the Right One&quot;">​</a></h2><p>Lodestone supports five transcript integrations, all of which bring meeting content into the Extracts module for AI analysis. The choice between them depends on what your team already uses — you can connect multiple.</p><table tabindex="0"><thead><tr><th>Integration</th><th>Primary use case</th><th>Best for</th><th>CRM enrichment</th></tr></thead><tbody><tr><td><strong>Fireflies</strong></td><td>General meeting transcription</td><td>Broad meeting coverage (internal + external)</td><td>No</td></tr><tr><td><strong>Gong</strong></td><td>Revenue-focused call intelligence</td><td>Customer-facing sales and CS calls</td><td>Yes — attaches company and revenue context</td></tr><tr><td><strong>Fathom</strong></td><td>Meeting notes and transcript capture</td><td>Teams using Fathom for automated notes</td><td>No</td></tr><tr><td><strong>Granola</strong></td><td>AI meeting notes</td><td>Teams using Granola for note-taking</td><td>No</td></tr><tr><td><strong>tl;dv</strong></td><td>Meeting recordings with transcript capture</td><td>Teams using tl;dv for call recording</td><td>No</td></tr></tbody></table><p>All five integrations are discovery-only — they bring transcripts and notes in; they do not sync any data back to the source system.</p><h3 id="gong-s-additional-value-crm-enrichment" tabindex="-1">Gong&#39;s additional value: CRM enrichment <a class="header-anchor" href="#gong-s-additional-value-crm-enrichment" aria-label="Permalink to &quot;Gong&#39;s additional value: CRM enrichment&quot;">​</a></h3><p>Gong is the only transcript integration that also enriches extracted features with CRM context. When Lodestone imports a Gong call, it automatically attaches company metadata from the associated Gong account to the extracted features. This means you can see not just what was said, but who said it — and whether that company represents high-value revenue. This makes Gong the strongest choice for teams where ARR/opportunity data should influence prioritization decisions.</p><hr><h2 id="how-integrations-affect-the-rest-of-lodestone" tabindex="-1">How Integrations Affect the Rest of Lodestone <a class="header-anchor" href="#how-integrations-affect-the-rest-of-lodestone" aria-label="Permalink to &quot;How Integrations Affect the Rest of Lodestone&quot;">​</a></h2><p>Integrations expand what Lodestone can see, but they don&#39;t change how Lodestone works. A few things to keep in mind:</p><ul><li><strong>Releases</strong> benefit most from JIRA sync — Feature status updates flow into Release boards automatically, making them live views of delivery progress without manual updates</li><li><strong>Extracts</strong> benefit most from Fireflies and Gong — transcripts flow in without manual upload, and the AI surfaces ideas directly from customer conversations</li><li><strong>Features</strong> are the integration anchor point for JIRA — every sync, link, and status update operates at the Feature level</li><li><strong>Asana</strong> benefits most from targeted use — push the Backlog items your team is actively tracking in Asana, and let status flow back automatically without manual updates in both systems</li><li><strong>Documents, Roadmaps, Strategies, and Auctions</strong> are not synced with any external system — they remain Lodestone-native artifacts</li></ul><hr><h2 id="what-happens-when-you-disconnect-an-integration" tabindex="-1">What Happens When You Disconnect an Integration <a class="header-anchor" href="#what-happens-when-you-disconnect-an-integration" aria-label="Permalink to &quot;What Happens When You Disconnect an Integration&quot;">​</a></h2><p>Disconnecting any integration stops all future syncing but preserves existing data in Lodestone:</p><ul><li><strong>JIRA disconnect</strong> — Features and their status history remain in Lodestone; future JIRA changes no longer flow through; existing JIRA links are preserved but inactive</li><li><strong>Asana disconnect</strong> — existing Asana task links on Backlog items are preserved but inactive; status updates from Asana stop flowing until reconnected</li><li><strong>Fireflies/Gong disconnect</strong> — previously imported transcripts and their generated Extracts (if still in the queue) are unaffected; future imports are no longer available until reconnected</li></ul><p>Reconnecting an integration restores sync behavior. You may need to reconfigure status mapping if it was reset during disconnection.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — common connection issues, sync problems, and status mapping errors.</em></p>',54)])])}const p=e(s,[["render",i]]);export{g as __pageData,p as default};
